const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;
const srcIp = body.data?.srcip ? body.data.srcip : (body.data?.win?.eventdata?.sourceAddress ? body.data.win.eventdata.sourceAddress : null);
const rawHashes = body.data?.win?.eventdata?.hashes ? body.data.win.eventdata.hashes : "";
const sha256Match = rawHashes.match(/SHA256=([a-fA-F0-9]{64})/i);
const sha256 = sha256Match ? sha256Match[1] : (body.syscheck?.sha256_after ? body.syscheck.sha256_after : null);
const hostname = body.agent?.name ? body.agent.name : "UNKNOWN-HOST";
const agentId = body.agent?.id ? body.agent.id : "000";
const ruleId = body.rule?.id ? body.rule.id : "0000";
const severity = Number(body.rule?.level ? body.rule.level : 0);
const iocPart = srcIp ? srcIp : (sha256 ? sha256 : "no_ioc");
const dedupKey = `${hostname}_${ruleId}_${iocPart}`;
const staticData = $getWorkflowStaticData('global');
if (!staticData.dedupCache) { staticData.dedupCache = {}; }
const now = Date.now();
for (const [k, ts] of Object.entries(staticData.dedupCache)) {
  if (now - ts > 900000) { delete staticData.dedupCache[k]; }
}
const isDuplicate = Boolean(staticData.dedupCache[dedupKey]);
if (!isDuplicate) { staticData.dedupCache[dedupKey] = now; }
return [{
  json: {
    dedup_key: dedupKey,
    is_duplicate: isDuplicate,
    alert_id: body.id ? body.id : `${now}`,
    timestamp: body.timestamp ? body.timestamp : new Date().toISOString(),
    rule_id: ruleId,
    severity: severity,
    description: body.rule?.description ? body.rule.description : "Security Event",
    mitre_ids: body.rule?.mitre?.id ? body.rule.mitre.id : [],
    hostname: hostname,
    agent_id: agentId,
    agent_ip: body.agent?.ip ? body.agent.ip : "N/A",
    username: body.data?.win?.eventdata?.user ? body.data.win.eventdata.user : "N/A",
    command_line: body.data?.win?.eventdata?.commandLine ? body.data.win.eventdata.commandLine : "N/A",
    ioc_ip: srcIp,
    ioc_sha256: sha256
  }
}];

const alert = $('2. Extract IOCs & 15m Dedup').first().json;
const assets = {
  "FINANCE-SRV-01": { department: "Finance", criticality: "CRITICAL (Tier-0 Crown Jewel)", owner: "secops@corp.local" },
  "AD-DC-01": { department: "Core Infra", criticality: "CRITICAL (Tier-0 Domain Controller)", owner: "infra@corp.local" }
};
const ctx = assets[alert.hostname] ? assets[alert.hostname] : { department: "Enterprise", criticality: "MEDIUM (Tier-2)", owner: "it@corp.local" };
return [{ json: { hostname: alert.hostname, asset_context: ctx } }];

function safeGet(nodeName) {
  try {
    return $(nodeName).first()?.json;
  } catch (e) {
    return {};
  }
}
const baseAlert = safeGet('2. Extract IOCs & 15m Dedup');
const abuseRes = safeGet('4a. AbuseIPDB Lookup');
const gnData = safeGet('4b. GreyNoise Scanner Check');
const vtRes = safeGet('4c. VirusTotal Hash Lookup');
const assetRes = safeGet('4d. Asset Criticality CMDB');

const abuseData = abuseRes?.data ? abuseRes.data : {};
const vtStats = vtRes?.data?.attributes?.last_analysis_stats ? vtRes.data.attributes.last_analysis_stats : {};
const assetInfo = assetRes?.asset_context ? assetRes.asset_context : {};

return [{
  json: {
    alert_telemetry: baseAlert,
    asset_cmdb: assetInfo,
    threat_intelligence: {
      abuseipdb_score: abuseData.abuseConfidenceScore !== undefined ? abuseData.abuseConfidenceScore : "Pending Key",
      greynoise_scanner: gnData?.noise !== undefined ? gnData.noise : false,
      greynoise_classification: gnData?.classification ? gnData.classification : "unknown",
      virustotal_malicious: vtStats.malicious !== undefined ? vtStats.malicious : 0
    }
  }
}];

