    confidence_score: 94,
    mitre_technique: "T1059.001 - PowerShell",
    root_cause_bullets: [
      `Host ${ctx.alert_telemetry.hostname} (${ctx.asset_cmdb.criticality}) executed hidden PowerShell cradle from ${ctx.alert_telemetry.ioc_ip}.`,
      `OSINT: AbuseIPDB=${ctx.threat_intelligence.abuseipdb_score}, VT Malicious=${ctx.threat_intelligence.virustotal_malicious}.`,
      `Immediate host containment required on Tier-0 asset.`
    ],
    remediation_cli: `wazuh-control active-response isolate-host --agent ${ctx.alert_telemetry.agent_id}`
  };
}
const base = "http://localhost:5678/webhook/soar-active-response";
const q = `agent_id=${ctx.alert_telemetry.agent_id}&hostname=${ctx.alert_telemetry.hostname}&ioc_ip=${ctx.alert_telemetry.ioc_ip}`;
return [{
  json: {
    ...ctx,
    ai_triage: ai,
    isolate_url: `${base}?action=isolate_host&${q}`,
    block_url: `${base}?action=block_ip&${q}`
  }
}];

